(function(E){ const x = E["exam-09"] = E["exam-09"] || {units:{}}; (x.units = x.units || {})["x09-l2"] = {"id":"x09-l2","patterns":["L2-local","PARA-place","TR-ruledout","TR-paraphrase"],"title":{"en":"Listening Part 2: local news and a map","tr":"Listening Part 2: yerel haberler ve bir harita","fa":"Listening Part 2: خبرهای محلی و یک نقشه"},"objective":{"en":"In this lesson you will learn to answer multiple choice questions on local news and to label a map by following a speaker’s directions step by step.","tr":"Bu derste yerel haberlerle ilgili çoktan seçmeli soruları cevaplamayı ve bir konuşanın yol tarifini adım adım takip ederek bir haritayı etiketlemeyi öğreneceksin.","fa":"در این درس یاد می‌گیری به سؤال‌های چندگزینه‌ای درباره‌ی خبرهای محلی جواب بدهی و با دنبال کردن قدم به قدم مسیرهایی که گوینده می‌گوید، روی نقشه برچسب بگذاری."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: local news and a map","tr":"Listening Part 2: yerel haberler ve bir harita","fa":"Listening Part 2: خبرهای محلی و یک نقشه"},"objective":{"en":"In this lesson you will learn to answer multiple choice questions on local news and to label a map by following a speaker’s directions step by step.","tr":"Bu derste yerel haberlerle ilgili çoktan seçmeli soruları cevaplamayı ve bir konuşanın yol tarifini adım adım takip ederek bir haritayı etiketlemeyi öğreneceksin.","fa":"در این درس یاد می‌گیری به سؤال‌های چندگزینه‌ای درباره‌ی خبرهای محلی جواب بدهی و با دنبال کردن قدم به قدم مسیرهایی که گوینده می‌گوید، روی نقشه برچسب بگذاری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Map letters","tr":"Harita harfleri","fa":"حرف‌های نقشه"},"value":"A-H"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a friendship-town association","tr":"Bu sınav: bir kardeş şehir derneği","fa":"این آزمون: انجمن شهرهای خواهرخوانده"},"intro":{"en":"Local facilities and community plans are a frequent Part 2 situation, and many of these talks end with a map or a plan. The speaker is friendly and informal, but the directions are precise.","tr":"Yerel tesisler ve topluluk planları Part 2’de sık çıkan bir durumdur; bu konuşmaların çoğu bir harita ya da planla biter. Konuşan samimi ve rahattır ama yol tarifleri kesindir.","fa":"امکانات محلی و برنامه‌های محله موقعیتی رایج در Part 2 است و خیلی از این صحبت‌ها با یک نقشه یا پلان تمام می‌شوند. گوینده صمیمی و راحت است، اما مسیرها دقیق‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x09-l2-ctx","exam":true,"patterns":["L2-local","PARA-place"],"often":{"pattern":"L2-local","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Club news and a plan of a new garden","tr":"Kulüp haberleri ve yeni bir bahçenin planı","fa":"خبرهای انجمن و نقشه‌ی یک باغ تازه"},"asks":{"en":"The leader of a local group gives members the latest news (dates, money, volunteers, fees, a gift) and then talks them through a map of a new garden, saying where each feature will go.","tr":"Yerel bir grubun başkanı üyelere son haberleri veriyor (tarihler, para, gönüllüler, aidatlar, bir hediye) ve sonra yeni bir bahçenin haritası üzerinden her şeyin nereye yapılacağını anlatıyor.","fa":"رئیس یک گروه محلی تازه‌ترین خبرها را به اعضا می‌دهد (تاریخ‌ها، پول، داوطلب‌ها، حق عضویت، یک هدیه) و بعد روی نقشه‌ی یک باغ تازه توضیح می‌دهد هر چیز کجا قرار می‌گیرد."},"fields":["Dates","Fundraising","Volunteers","Membership","A gift","The map: where each feature will go"],"words":[{"a":"impossible","b":"it won’t work for them / clashes with","tr":"imkânsız","fa":"غیرممکن"},{"a":"raised the most money","b":"brought in more than the others","tr":"en çok parayı topladı","fa":"بیشترین پول را جمع کرد"},{"a":"most needed","b":"what we’re really short of","tr":"en çok ihtiyaç duyulan","fa":"بیشترین نیاز"},{"a":"free for","b":"no longer have to pay","tr":"... için ücretsiz","fa":"برای ... رایگان"},{"a":"staying the same","b":"is not going up / remains at","tr":"aynı kalıyor","fa":"ثابت می‌ماند"},{"a":"as soon as you come in","b":"just inside the gate","tr":"girer girmez","fa":"همین که وارد شدی"},{"a":"at the far end","b":"all the way along / right at the end","tr":"en uçta","fa":"در انتهای دور"},{"a":"opposite","b":"on the other side / facing","tr":"karşısında","fa":"روبه‌روی"},{"a":"beyond","b":"past / on the other side of","tr":"ötesinde","fa":"آن طرفِ"},{"a":"just north of","b":"a little above, on the map","tr":"hemen kuzeyinde","fa":"کمی شمالِ"},{"a":"in the top left-hand corner","b":"north-west corner","tr":"sol üst köşede","fa":"گوشه‌ی بالا سمت چپ"},{"a":"turn left","b":"go left / take the path on your left","tr":"sola dön","fa":"به چپ بپیچ"}],"traps":[{"en":"A plan is changed: \"It was going to go in the centre, but... so instead it will stand...\" Label the new place.","tr":"Bir plan değişir: \"Ortaya konacaktı ama... bu yüzden onun yerine...\" Yeni yeri işaretle.","fa":"یک برنامه عوض می‌شود: «قرار بود وسط باشد، اما... پس به‌جایش...». جای تازه را علامت بزن."},{"en":"Left and right depend on where the speaker is standing. Follow the route on the map with your finger.","tr":"Sol ve sağ, konuşanın nerede durduğuna bağlıdır. Haritadaki yolu parmağınla takip et.","fa":"چپ و راست به جایی بستگی دارد که گوینده ایستاده. مسیر را روی نقشه با انگشتت دنبال کن."},{"en":"News items mention three options: \"we did suggest... but...\", \"people guessed...\". Wait for the final fact.","tr":"Haberlerde üç seçenekten söz edilir: \"önermiştik... ama...\", \"insanlar tahmin etti...\". Son bilgiyi bekle.","fa":"در خبرها از سه گزینه حرف زده می‌شود: «پیشنهاد کردیم... اما...»، «مردم حدس زدند...». منتظر واقعیت نهایی بمان."}],"example":{"lines":[["Speaker","Walk in through the gate and go straight ahead. The fountain is on your right, just past the toilets."]],"item":"Map: the fountain is ___ (gate at the bottom, toilets on the right of the path)","answer":"on the right of the path, after the toilets","why":{"en":"Start at the gate, face up the map, then find the toilets and move one step past them.","tr":"Kapıdan başla, haritada yukarıya bak, sonra tuvaletleri bul ve bir adım geçerek ilerle.","fa":"از دروازه شروع کن، رو به بالای نقشه بایست، بعد دستشویی‌ها را پیدا کن و یک قدم از آن‌ها جلوتر برو."}}},{"id":"L2-local","ctx":["L2-local"],"title":{"en":"Local facilities and council plans","tr":"Yerel olanaklar ve belediye planları","fa":"امکانات محلی و طرح‌های شهرداری"},"asks":{"en":"Someone from the council or a community group talks about parks, roads, a housing plan, a school site or a local service. Questions ask what will change, why, when, and what local people think.","tr":"Belediyeden ya da bir mahalle grubundan biri parklar, yollar, bir konut planı, bir okul alanı ya da yerel bir hizmet hakkında konuşur. Sorular neyin, neden ve ne zaman değişeceğini ve halkın ne düşündüğünü sorar.","fa":"کسی از شهرداری یا یک گروه محلی درباره‌ی پارک‌ها، خیابان‌ها، یک طرح مسکونی، زمین یک مدرسه یا یک خدمت محلی حرف می‌زند. سؤال‌ها می‌پرسند چه چیزی، چرا و کی عوض می‌شود و مردم محل چه فکر می‌کنند."},"fields":["What is the main reason for the change?","What will happen to the old building?","Which TWO facilities will be added?","What did residents complain about most?","When will the work be finished?","What change is planned for each place?"],"words":[{"a":"residents","b":"people who live here / locals","tr":"mahalle sakinleri","fa":"ساکنان"},{"a":"council","b":"the local authority / the town hall","tr":"belediye","fa":"شهرداری"},{"a":"facilities","b":"toilets, a cafe, a playground","tr":"olanaklar, tesisler","fa":"امکانات"},{"a":"replace","b":"swap X for Y / instead of","tr":"yerine koymak","fa":"جایگزین کردن"},{"a":"extend","b":"make bigger / add to","tr":"genişletmek","fa":"بزرگ‌تر کردن"},{"a":"complaint","b":"people weren't happy about","tr":"şikâyet","fa":"شکایت"},{"a":"funding","b":"the money comes from","tr":"finansman","fa":"بودجه"},{"a":"consult","b":"ask people what they think","tr":"görüş almak","fa":"نظرخواهی کردن"},{"a":"pedestrians","b":"people on foot","tr":"yayalar","fa":"عابران پیاده"},{"a":"temporarily","b":"for now / until the work is finished","tr":"geçici olarak","fa":"موقتاً"},{"a":"due to open","b":"it should be ready by","tr":"açılması planlanan","fa":"قرار است باز شود"},{"a":"knock down","b":"demolish / pull down","tr":"yıkmak","fa":"خراب کردن"}],"traps":[{"en":"A plan is described and then dropped: \"we did think about a car park, but...\".","tr":"Bir plan anlatılır, sonra vazgeçilir: \"bir otopark da düşündük ama...\".","fa":"یک طرح گفته می‌شود و بعد کنار گذاشته می‌شود: «به پارکینگ هم فکر کردیم، ولی...»."},{"en":"The question asks for the residents’ view; the speaker gives the council’s view first.","tr":"Soru halkın görüşünü sorar; konuşmacı önce belediyenin görüşünü verir.","fa":"سؤال نظر ساکنان را می‌پرسد؛ گوینده اول نظر شهرداری را می‌گوید."},{"en":"Two dates: when the work starts and when it finishes. Check which one the question needs.","tr":"İki tarih: işin başladığı ve bittiği tarih. Sorunun hangisini istediğine bak.","fa":"دو تاریخ: شروع کار و پایان کار. ببین سؤال کدام را می‌خواهد."}],"example":{"lines":[["Councillor","We did think about building a car park on the old sports ground."],["Councillor","But residents told us they wanted green space."],["Councillor","So instead we’re turning it into a community garden, which should open in the spring."]],"item":"What will happen to the old sports ground?  A a car park   B a community garden   C a sports hall","answer":"B","why":{"en":"The car park was considered and dropped. \"Instead\" brings the real plan: a community garden.","tr":"Otopark düşünülmüş ve vazgeçilmiş. \"Instead\" gerçek planı getiriyor: bir topluluk bahçesi.","fa":"پارکینگ بررسی و کنار گذاشته شد. «Instead» طرح واقعی را می‌آورد: باغ محلی."}},"general":true,"patterns":["L2-local"],"often":{"pattern":"L2-local","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"L2-map-parks","ctx":["L2-map-parks","L2-local"],"title":{"en":"Parks, gardens and walking routes","tr":"Parklar, bahçeler ve yürüyüş yolları","fa":"پارک، باغ و مسیر پیاده‌روی"},"asks":{"en":"A speaker describes a park, a recreation ground or a walking route, often with new or moved facilities. You label places such as the cafe, the toilets, a playground, a picnic area or a viewpoint.","tr":"Konuşmacı bir parkı, bir rekreasyon alanını ya da bir yürüyüş yolunu, çoğu zaman yeni ya da yeri değişen olanaklarla anlatır. Kafe, tuvaletler, oyun parkı, piknik alanı ya da seyir noktası gibi yerleri etiketlersin.","fa":"گوینده یک پارک، یک فضای تفریحی یا یک مسیر پیاده‌روی را توصیف می‌کند، اغلب با امکاناتی که تازه ساخته شده یا جابه‌جا شده‌اند. جاهایی مثل کافه، دستشویی، زمین بازی، محل پیک‌نیک یا نقطه‌ی دیدنی را برچسب می‌زنی."},"fields":["Cafe","Toilets","Children’s playground","Picnic area","Outdoor gym","Viewpoint","Bird hide"],"words":[{"a":"entrance","b":"as you come in / where you enter","tr":"giriş","fa":"ورودی"},{"a":"path","b":"the track / the walkway","tr":"patika","fa":"مسیر"},{"a":"footbridge","b":"the little bridge over the stream","tr":"yaya köprüsü","fa":"پل عابر پیاده"},{"a":"picnic area","b":"where you can eat outside","tr":"piknik alanı","fa":"محل پیک‌نیک"},{"a":"playground","b":"the swings and slides","tr":"oyun parkı","fa":"زمین بازی بچه‌ها"},{"a":"viewpoint","b":"where you can see the whole valley","tr":"seyir noktası","fa":"نقطه‌ی دیدنی"},{"a":"bird hide","b":"a small hut for watching birds","tr":"kuş gözlem kulübesi","fa":"کلبه‌ی تماشای پرنده"},{"a":"outdoor gym","b":"exercise machines in the open air","tr":"açık hava spor alanı","fa":"باشگاه روباز"},{"a":"in the corner","b":"where the two fences meet","tr":"köşede","fa":"در گوشه"},{"a":"alongside","b":"running next to","tr":"boyunca","fa":"در امتداد"},{"a":"beyond","b":"further on, past it","tr":"ötesinde","fa":"آن طرفِ"},{"a":"at the far end","b":"the end away from you","tr":"en uçta","fa":"ته"},{"a":"opposite","b":"facing it, on the other side","tr":"karşısında","fa":"روبه‌روی"}],"traps":[{"en":"\"It used to be by the gate, but it’s been moved.\" Label the new place.","tr":"\"Eskiden kapının yanındaydı ama taşındı.\" Yeni yeri etiketle.","fa":"«قبلاً کنار در بود، ولی جابه‌جا شده». جای جدید را برچسب بزن."},{"en":"Directions are given from where the speaker stands: \"on your left as you face the lake\". Find that point on the plan first.","tr":"Yönler konuşmacının durduğu yere göre verilir: \"göle bakarken solunda\". Önce o noktayı planda bul.","fa":"جهت‌ها از جایی که گوینده ایستاده گفته می‌شوند: «وقتی رو به دریاچه هستی، سمت چپت». اول آن نقطه را روی پلان پیدا کن."},{"en":"Two places side by side: \"next to the toilets, not the cafe\". Listen for the second reference point.","tr":"Yan yana iki yer: \"kafenin değil, tuvaletlerin yanında\". İkinci referans noktasını dinle.","fa":"دو جای کنار هم: «کنار دستشویی، نه کافه». به نقطه‌ی مرجع دوم گوش کن."}],"example":{"lines":[["Speaker","Come in through the north gate and follow the path round the lake."],["Speaker","The outdoor gym used to be by the tennis courts."],["Speaker","It’s now on the far side of the lake, right next to the toilets."]],"item":"Outdoor gym: ___   (plan: north gate at the top, lake in the centre; G by the tennis courts, H beside the toilets on the far side of the lake, I by the gate)","answer":"H","why":{"en":"G is the old place. \"Now on the far side of the lake, right next to the toilets\" is H.","tr":"G eski yer. \"Now on the far side of the lake, right next to the toilets\" H’dir.","fa":"G جای قبلی است. «Now on the far side of the lake, right next to the toilets» یعنی H."}},"general":true,"patterns":["L2-local"],"often":{"pattern":"L2-local","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Five choices, then a map","tr":"Beş seçim, sonra bir harita","fa":"پنج سؤال چندگزینه‌ای، بعد یک نقشه"},"body":{"en":"Questions 11-15: choose A, B or C. Questions 16-20: write the letter, A-H, of each place on the map; three letters are not used. There is a pause before Question 16 to study the map.","tr":"Soru 11-15: A, B ya da C’yi seç. Soru 16-20: haritadaki her yerin harfini (A-H) yaz; üç harf kullanılmaz. Soru 16’dan önce haritayı incelemek için bir ara vardır.","fa":"سؤال‌های ۱۱ تا ۱۵: A، B یا C را انتخاب کن. سؤال‌های ۱۶ تا ۲۰: حرف هر مکان روی نقشه (A تا H) را بنویس؛ سه حرف استفاده نمی‌شوند. قبل از سؤال ۱۶ یک مکث برای دیدن نقشه هست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps for a map","tr":"Harita için dört adım","fa":"چهار قدم برای نقشه"},"steps":[{"en":"In the pause, find the starting point (the gate, the entrance) and the fixed features: paths, buildings, a lawn.","tr":"Arada başlangıç noktasını (kapı, giriş) ve sabit öğeleri bul: yollar, binalar, bir çim alan.","fa":"در مکث، نقطه‌ی شروع (دروازه، ورودی) و چیزهای ثابت را پیدا کن: مسیرها، ساختمان‌ها، چمن."},{"en":"Put your finger on the start and move it as the speaker moves: \"turn left\", \"go up\", \"at the end\".","tr":"Parmağını başlangıca koy ve konuşan ilerledikçe onu hareket ettir: \"turn left\", \"go up\", \"at the end\".","fa":"انگشتت را روی نقطه‌ی شروع بگذار و همراه گوینده جابه‌جا کن: «turn left»، «go up»، «at the end»."},{"en":"The places come in question order, so after each answer go back to the start the speaker names.","tr":"Yerler soru sırasıyla gelir; her cevaptan sonra konuşanın söylediği başlangıca geri dön.","fa":"مکان‌ها به ترتیب سؤال‌ها می‌آیند، پس بعد از هر جواب به نقطه‌ای برگرد که گوینده می‌گوید."},{"en":"If a place moves (\"was going to... but instead\"), label the final position.","tr":"Bir yer değişirse (\"...olacaktı ama onun yerine\") son konumu işaretle.","fa":"اگر جایی عوض شد («قرار بود... اما به‌جایش»)، جای نهایی را علامت بزن."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Words for position","tr":"Konum bildiren kelimeler","fa":"کلمه‌های مکان"},"table":{"headers":{"en":["You hear","On the map"],"tr":["Duyduğun","Haritada"],"fa":["می‌شنوی","روی نقشه"]},"rows":[["as soon as you come in","right by the entrance"],["all the way along to the far corner","the corner furthest from you"],["at the opposite end of","the other end of the same path"],["beyond the café","on the far side of the café"],["just north of","a little higher up the map"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One map label, step by step","tr":"Bir harita etiketi, adım adım","fa":"یک برچسب نقشه، قدم به قدم"},"instruction":"Label the map below. Write the correct letter, A-F.","item":"Where is the bike shed? (Map: car park at the bottom; a path goes up to a library; a pond on the left half-way up.)","lines":[["Speaker","From the car park, walk up the path towards the library. Just before you reach the pond, there’s a little path on the right. The bike shed is at the end of that."]],"answer":"the letter at the end of the small path on the right, below the pond","walk":[{"en":"Start: the car park at the bottom. Move up the path.","tr":"Başlangıç: alttaki otopark. Yol boyunca yukarı çık.","fa":"شروع: پارکینگ پایین. در مسیر بالا برو."},{"en":"\"Just before the pond\": stop below the pond.","tr":"\"Göletten hemen önce\": göletin altında dur.","fa":"«درست قبل از برکه»: زیر برکه بایست."},{"en":"\"On the right... at the end of that\": follow the side path to its end.","tr":"\"Sağda... onun sonunda\": yan yolu sonuna kadar takip et.","fa":"«سمت راست... انتهای آن»: مسیر فرعی را تا آخرش دنبال کن."}]},"quick":{"prompt":"\"The play area was going to be next to the café, but because of the noise, we’ve put it at the far end of the garden.\" Where is the play area?","options":["next to the café","in the middle of the garden","at the far end of the garden"],"correct":2,"why":{"en":"\"Was going to be\" is the old plan; \"we’ve put it\" gives the final place.","tr":"\"Was going to be\" eski plan; \"we’ve put it\" son yeri veriyor.","fa":"«was going to be» برنامه‌ی قبلی است؛ «we’ve put it» جای نهایی را می‌گوید."}},"remember":{"en":"Find the start, move your finger with the speaker, and label the final position.","tr":"Başlangıcı bul, parmağını konuşanla birlikte hareket ettir ve son konumu işaretle.","fa":"نقطه‌ی شروع را پیدا کن، انگشتت را همراه گوینده جابه‌جا کن و جای نهایی را علامت بزن."},"type":"explain","id":"c-x09-l2-e","course":"ielts-exams","exam":"exam-09","unit":"x09-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"Friendship Town Association: news and the new garden","tr":"Kardeş Şehir Derneği: haberler ve yeni bahçe","fa":"انجمن شهرهای خواهرخوانده: خبرها و باغ تازه"},"timed":7,"ctx":["L2-local"],"script":[{"who":"Chair","line":"Good evening, everyone, and thank you for coming out on such a cold night. As chair of the Friendship Town Association, I've got some news to share, and then I'd like to show you the plans for the new Friendship Garden."},{"who":"Chair","line":"First, the visit from our partner town, Saint-Aubin. Many of you will remember that the group usually comes over in May. This year, though, the French school holidays have changed, and May is impossible for them. We did suggest September, but that clashes with their grape harvest, which half the town works on. So we've agreed that they'll arrive in the second week of June and stay for six nights."},{"who":"Chair","line":"Next, money. Last year we held three fundraising events. The quiz night was probably the one people enjoyed most, judging by the noise, and the cake stall at the summer fair did well too. But the event that really made a difference was the plant sale in April. It brought in more than the other two put together, so we'll definitely repeat it, and I hope those of you with gardens are already growing seedlings for us."},{"who":"Chair","line":"Now, volunteers. Every year I worry that we won't find enough families to host our visitors, and every year you prove me wrong, so thank you. We're also lucky to have several members who speak excellent French, so translating at the welcome dinner won't be a problem. What we're really short of this year is people to drive the minibus. We need at least four drivers for the trips to the coast and to the castle, and you'll need a full licence held for at least three years."},{"who":"Chair","line":"On membership, I'm pleased to say that the annual fee is staying at fifteen pounds. Some of you asked whether you could pay monthly, but the bank charges would cost us more than we'd gain, I'm afraid. What the committee has agreed is that membership will now be free for students in full-time education, because we'd love to have more young people involved."},{"who":"Chair","line":"And finally, a gift. Saint-Aubin has very kindly sent us something for the new garden. When I mentioned this at the last meeting, several people guessed it would be a statue, and someone even hoped for a fountain. In fact, it's a sundial, carved from the same pale stone as their town hall, with the names of both towns around the edge."},{"who":"Chair","line":"Which brings me to the garden itself. If you look at the map on the screen, you'll see Mill Lane running along the bottom, with the main gate in the middle. A wide path runs straight up from the gate to the café at the top, and halfway up there's a round lawn, where a second path crosses from one side of the garden to the other."},{"who":"Chair","line":"Let's start at the gate. If you turn right as soon as you come in, and follow the wall all the way along to the far corner, that's where the pond will be. It's a quiet, sheltered spot, and there'll be a low fence round it for safety."},{"who":"Chair","line":"Now go back to the main path and walk up to the round lawn. If you turn left there, along the cross path, you'll find the herb beds right at the end of it, against the west wall. They get the afternoon sun, which herbs love."},{"who":"Chair","line":"The sundial was going to go in the very centre of the lawn. But the big oak tree next to it would put it in the shade for half the day, which isn't much use for a sundial. So instead it will stand just north of the lawn, on the main path, where the path begins to rise towards the café."},{"who":"Chair","line":"Beyond the café, in the top left-hand corner of the garden, we'll put up the greenhouse. That's where the seedlings for next year's plant sale will be grown."},{"who":"Chair","line":"And lastly, the picnic area. That'll be at the opposite end of the cross path from the herb beds, on the east side of the garden, with tables and a couple of benches. Right, I'll leave the map up while we have a short break."}],"map":{"title":"Friendship Garden","orientation":"north at the top","coords":"0-100 from the top-left corner","features":[{"label":"Mill Lane","type":"road","from":[0,100],"to":[100,100]},{"label":"Main gate","type":"gate","at":[50,97]},{"label":"Café","type":"building","at":[50,8]},{"type":"path","from":[50,95],"to":[50,12]},{"type":"path","from":[8,50],"to":[92,50]},{"label":"Round lawn","type":"lawn","at":[50,50],"r":8},{"label":"Oak tree","type":"tree","at":[62,42]},{"type":"wall","around":true}],"letters":[{"l":"A","at":[38,88]},{"l":"B","at":[62,88]},{"l":"C","at":[9,50]},{"l":"D","at":[50,50]},{"l":"E","at":[50,37]},{"l":"F","at":[91,50]},{"l":"G","at":[10,8]},{"l":"H","at":[92,93]}]},"groups":[{"instruction":"Questions 11-15. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":11,"kind":"mcq","prompt":"When will the group from Saint-Aubin arrive?","options":["A in May","B in June","C in September"],"correct":1,"evidence":"they'll arrive in the second week of June","why":{"en":"May is \"impossible\" this year and September clashes with the grape harvest. They come in June.","tr":"Mayıs bu yıl \"imkânsız\", eylül de üzüm hasadıyla çakışıyor. Haziranda geliyorlar.","fa":"ماه مه امسال «غیرممکن» است و سپتامبر با برداشت انگور هم‌زمان می‌شود. ژوئن می‌آیند."},"trap":["TR-ruledout"]},{"n":12,"kind":"mcq","prompt":"Which event raised the most money last year?","options":["A the plant sale","B the quiz night","C the cake stall"],"correct":0,"evidence":"It brought in more than the other two put together","why":{"en":"The quiz night was the most enjoyed; the plant sale \"brought in more than the other two put together\".","tr":"En çok bilgi yarışması gecesi sevildi; bitki satışı \"diğer ikisinin toplamından fazla\" getirdi.","fa":"شب مسابقه از همه دلپذیرتر بود؛ فروش گیاه «بیشتر از جمع آن دو تای دیگر» درآمد داشت."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":13,"kind":"mcq","prompt":"The association most needs volunteers to","options":["A host visitors in their homes.","B translate at the welcome dinner.","C drive the minibus."],"correct":2,"evidence":"What we're really short of this year is people to drive the minibus","why":{"en":"Hosts and French speakers are not a problem. \"What we’re really short of\" = what is most needed: drivers.","tr":"Ev sahipleri ve Fransızca konuşanlar sorun değil. \"Asıl eksik olan\" = en çok ihtiyaç duyulan: sürücüler.","fa":"میزبان و فرانسوی‌دان مشکلی نیست. «چیزی که واقعاً کم داریم» یعنی بیشترین نیاز: راننده."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":14,"kind":"mcq","prompt":"What has changed about membership?","options":["A The fee has gone up.","B Students no longer have to pay.","C Members can now pay monthly."],"correct":1,"evidence":"membership will now be free for students","why":{"en":"The fee \"is staying at fifteen pounds\", monthly payment was refused, and students now join free.","tr":"Ücret \"on beş poundta kalıyor\", aylık ödeme reddedildi, öğrenciler artık ücretsiz katılıyor.","fa":"حق عضویت «همان پانزده پوند می‌ماند»، پرداخت ماهانه رد شد و دانشجوها حالا رایگان عضو می‌شوند."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":15,"kind":"mcq","prompt":"What has Saint-Aubin sent for the garden?","options":["A a sundial","B a statue","C a fountain"],"correct":0,"evidence":"In fact, it's a sundial","why":{"en":"People guessed a statue or a fountain. \"In fact, it’s a sundial.\"","tr":"İnsanlar heykel ya da çeşme tahmin etti. \"Aslında bir güneş saati.\"","fa":"مردم حدس زدند مجسمه یا فواره باشد. «در واقع یک ساعت آفتابی است»."},"trap":["TR-ruledout"]}]},{"instruction":"Questions 16-20. Label the map below. Write the correct letter, A-H, next to Questions 16-20.","qtype":"map","bank":["A","B","C","D","E","F","G","H"],"questions":[{"n":16,"kind":"match","prompt":"pond","correct":7,"evidence":"that's where the pond will be","why":{"en":"Turn right inside the gate and follow the wall \"to the far corner\": H, bottom right.","tr":"Kapıdan girince sağa dön ve duvarı \"en uzak köşeye kadar\" takip et: H, sağ alt.","fa":"داخل دروازه به راست بپیچ و دیوار را «تا گوشه‌ی دور» دنبال کن: H، پایین سمت راست."},"trap":["TR-paraphrase"]},{"n":17,"kind":"match","prompt":"herb beds","correct":2,"evidence":"you'll find the herb beds right at the end of it","why":{"en":"Left along the cross path, \"right at the end of it, against the west wall\": C.","tr":"Çapraz yolda sola, \"tam sonunda, batı duvarının dibinde\": C.","fa":"در مسیر عرضی به چپ، «درست انتهایش، کنار دیوار غربی»: C."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"sundial","correct":4,"evidence":"it will stand just north of the lawn","why":{"en":"Not the centre of the lawn (D), because of the shade: \"just north of the lawn, on the main path\": E.","tr":"Gölge yüzünden çimin ortası (D) değil: \"çimin hemen kuzeyinde, ana yolda\": E.","fa":"به‌خاطر سایه نه وسط چمن (D): «کمی شمالِ چمن، روی مسیر اصلی»: E."},"trap":["TR-ruledout"]},{"n":19,"kind":"match","prompt":"greenhouse","correct":6,"evidence":"in the top left-hand corner of the garden","why":{"en":"\"Beyond the café, in the top left-hand corner\": G.","tr":"\"Kafenin ötesinde, sol üst köşede\": G.","fa":"«آن طرف کافه، در گوشه‌ی بالا سمت چپ»: G."},"trap":["TR-paraphrase"]},{"n":20,"kind":"match","prompt":"picnic area","correct":5,"evidence":"at the opposite end of the cross path from the herb beds","why":{"en":"Opposite the herb beds, at the east end of the cross path: F.","tr":"Bitki yataklarının karşısında, çapraz yolun doğu ucunda: F.","fa":"روبه‌روی باغچه‌ی سبزی‌ها، در انتهای شرقی مسیر عرضی: F."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Chair":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_lily"},"role":"Chair of a friendship-town association"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear the chair of a friendship-town association talking to members at a meeting. First, you have some time to look at Questions 11 to 15."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-15"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 15."},{"type":"sfx","note":"small hall: light room tone, a few chairs moving at the start"},{"type":"lines","from":0,"to":5},{"type":"announcer","text":"Before you hear the rest of the talk, you have some time to look at Questions 16 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 16-20 (study the map)"},{"type":"announcer","text":"Now listen and answer Questions 16 to 20."},{"type":"lines","from":6,"to":11},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x09-l2-d","course":"ielts-exams","exam":"exam-09","unit":"x09-l2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The date clashes with the harvest.\" This means...","options":["the harvest is cancelled","both happen at the same time","the date is fixed"],"correct":1,"why":{"en":"To clash = to happen at the same time, so you cannot do both.","tr":"Clash = aynı anda olmak; ikisini birden yapamazsın.","fa":"clash یعنی هم‌زمان شدن، طوری که نمی‌شود هر دو را انجام داد."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means the same as \"at the opposite end of the path\"?","options":["at the other end of the same path","next to the path","halfway along the path"],"correct":0,"why":{"en":"Opposite end = the other end of the same path.","tr":"Karşı uç = aynı yolun öbür ucu.","fa":"انتهای مقابل یعنی سر دیگرِ همان مسیر."}},{"tests":"method","point":2,"prompt":"The speaker says \"Now go back to the main path.\" What should you do on the map?","options":["Stay at the last place you labelled","Start again from the gate","Move your finger back to the main path"],"correct":2,"why":{"en":"Follow the new starting point exactly as the speaker gives it.","tr":"Konuşanın verdiği yeni başlangıç noktasını aynen takip et.","fa":"نقطه‌ی شروع تازه را دقیقاً همان‌طور که گوینده می‌گوید دنبال کن."}},{"tests":"trap","point":3,"prompt":"\"The benches were going to go by the pond, but we’ve moved them under the trees.\" Where are the benches now?","options":["by the pond","under the trees","both places"],"correct":1,"why":{"en":"\"Were going to go\" is the old plan; \"we’ve moved them\" is the final position.","tr":"\"Were going to go\" eski plan; \"we’ve moved them\" son konum.","fa":"«were going to go» برنامه‌ی قبلی است؛ «we’ve moved them» جای نهایی است."}},{"tests":"trap","point":1,"prompt":"\"Several people guessed it would be a painting, but it’s actually a clock.\" What is the gift?","options":["a clock","a painting","we don’t know"],"correct":0,"why":{"en":"What people guessed is the distractor; \"actually\" gives the answer.","tr":"İnsanların tahmini çeldirici; \"actually\" cevabı veriyor.","fa":"حدس مردم گزینه‌ی انحرافی است؛ «actually» جواب را می‌دهد."}}],"id":"c-x09-l2-x","course":"ielts-exams","exam":"exam-09","unit":"x09-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
